import { Controller, Get, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const STATUSES = ['재직', '휴직', '단축근무', '퇴직'];
const GENDERS = ['M', 'F'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_HR_RECORD_INPUT', message);
}

function textOf(v: unknown, label: string, max: number): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || v.length > max) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return v;
}

function dateOf(v: unknown, label: string): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !DATE_RE.test(v)) {
    throw invalid(label + ' 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  return v;
}

function idOf(v: unknown, label: string): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'number' || !Number.isInteger(v) || v <= 0) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return v;
}

function salaryOf(v: unknown): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) {
    throw invalid('기본급은 0 이상의 숫자여야 합니다.');
  }
  return v;
}

function statusOf(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !STATUSES.includes(v)) {
    throw invalid('재직 구분 값이 올바르지 않습니다.');
  }
  return v;
}

function genderOf(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !GENDERS.includes(v)) {
    throw invalid('성별 값이 올바르지 않습니다.');
  }
  return v;
}

@Controller('api/v1')
export class FnSfr01201Controller {
  @Post('/hr-records')
  @HttpCode(200)
  async createHrRecord(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원 ID');
    if (employeeId === null) {
      throw invalid('임직원 ID는 필수입니다.');
    }
    const employmentStatus = statusOf(data['employmentStatus']);
    if (employmentStatus === null) {
      throw invalid('재직 구분은 필수입니다.');
    }
    const departmentId = idOf(data['departmentId'], '소속 부서 ID');
    const positionName = textOf(data['positionName'], '직위', 100);
    const birthDate = dateOf(data['birthDate'], '생년월일');
    const gender = genderOf(data['gender']);
    const address = textOf(data['address'], '주소', 500);
    const phoneNo = textOf(data['phoneNo'], '연락처', 30);
    const hireDate = dateOf(data['hireDate'], '입사일');
    const retirementDate = dateOf(data['retirementDate'], '퇴직일');
    const baseSalary = salaryOf(data['baseSalary']);
    const bankName = textOf(data['bankName'], '급여 은행명', 100);
    if (employmentStatus === '퇴직' && retirementDate === null) {
      throw invalid('퇴직으로 등록하려면 퇴직일을 입력해 주세요.');
    }
    // TODO: residentNoEnc(주민등록번호)·bankAccount(급여계좌번호)는 암호화 방식(키·알고리즘)이 입력에 없어 저장하지 않는다.
    return transaction(async (db) => {
      const emp = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (emp.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      if (departmentId !== null) {
        const dep = await db.query(
          'SELECT department_id FROM department WHERE department_id = CAST(:departmentId AS bigint)',
          { departmentId },
        );
        if (dep.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '소속 부서를 찾을 수 없습니다.');
        }
      }
      const dup = await db.query(
        'SELECT hr_record_id FROM hr_record WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'CONFLICT', '이미 인사정보가 등록된 임직원입니다.');
      }
      const rows = await db.query(
        `INSERT INTO hr_record (
           employee_id, department_id, position_name, birth_date, gender, address, phone_no,
           employment_status, hire_date, retirement_date, base_salary, bank_name, created_at, updated_at
         ) VALUES (
           CAST(:employeeId AS bigint), CAST(:departmentId AS bigint), :positionName,
           CAST(:birthDate AS date), :gender, :address, :phoneNo,
           :employmentStatus, CAST(:hireDate AS date), CAST(:retirementDate AS date),
           CAST(:baseSalary AS numeric), :bankName, now(), now()
         )
         RETURNING hr_record_id AS "hrRecordId", employee_id AS "employeeId", employment_status AS "employmentStatus"`,
        {
          employeeId,
          departmentId,
          positionName,
          birthDate,
          gender,
          address,
          phoneNo,
          employmentStatus,
          hireDate,
          retirementDate,
          baseSalary,
          bankName,
        },
      );
      return rows[0];
    });
  }

  @Patch('/hr-records/:hrRecordId')
  async updateHrRecord(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const idText = req.params['hrRecordId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(404, 'HR_RECORD_NOT_FOUND', '대상 인사정보를 찾을 수 없습니다.');
    }
    const data = checks.inputOf(req.body);
    const departmentId = idOf(data['departmentId'], '소속 부서 ID');
    const positionName = textOf(data['positionName'], '직위', 100);
    const address = textOf(data['address'], '주소', 500);
    const phoneNo = textOf(data['phoneNo'], '연락처', 30);
    const employmentStatus = statusOf(data['employmentStatus']);
    const hireDate = dateOf(data['hireDate'], '입사일');
    const retirementDate = dateOf(data['retirementDate'], '퇴직일');
    const baseSalary = salaryOf(data['baseSalary']);
    const bankName = textOf(data['bankName'], '급여 은행명', 100);
    // TODO: bankAccount(급여계좌번호)는 암호화 방식이 입력에 없어 저장하지 않는다.
    return transaction(async (db) => {
      const current = await db.query(
        `SELECT employment_status AS "employmentStatus", to_char(retirement_date, 'YYYY-MM-DD') AS "retirementDate"
         FROM hr_record WHERE hr_record_id = CAST(:id AS bigint)`,
        { id: idText },
      );
      if (current.length === 0) {
        throw new ApiError(404, 'HR_RECORD_NOT_FOUND', '대상 인사정보를 찾을 수 없습니다.');
      }
      const nextStatus = employmentStatus ?? (current[0]['employmentStatus'] as string);
      const nextRetirement = retirementDate ?? (current[0]['retirementDate'] as string | null);
      if (nextStatus === '퇴직' && !nextRetirement) {
        throw invalid('퇴직으로 변경하려면 퇴직일을 입력해 주세요.');
      }
      if (departmentId !== null) {
        const dep = await db.query(
          'SELECT department_id FROM department WHERE department_id = CAST(:departmentId AS bigint)',
          { departmentId },
        );
        if (dep.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '소속 부서를 찾을 수 없습니다.');
        }
      }
      const rows = await db.query(
        `UPDATE hr_record SET
           department_id = COALESCE(CAST(:departmentId AS bigint), department_id),
           position_name = COALESCE(:positionName, position_name),
           address = COALESCE(:address, address),
           phone_no = COALESCE(:phoneNo, phone_no),
           employment_status = COALESCE(:employmentStatus, employment_status),
           hire_date = COALESCE(CAST(:hireDate AS date), hire_date),
           retirement_date = COALESCE(CAST(:retirementDate AS date), retirement_date),
           base_salary = COALESCE(CAST(:baseSalary AS numeric), base_salary),
           bank_name = COALESCE(:bankName, bank_name),
           updated_at = now()
         WHERE hr_record_id = CAST(:id AS bigint)
         RETURNING hr_record_id AS "hrRecordId", employment_status AS "employmentStatus",
           to_char(retirement_date, 'YYYY-MM-DD') AS "retirementDate"`,
        {
          id: idText,
          departmentId,
          positionName,
          address,
          phoneNo,
          employmentStatus,
          hireDate,
          retirementDate,
          baseSalary,
          bankName,
        },
      );
      return rows[0];
    });
  }

  @Get('/hr-records')
  async listHrRecords(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const q = checks.queryOf(req.query);
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const size = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page·size 값이 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, 200);
    const statusRaw = q['employmentStatus'];
    let employmentStatus: string | null = null;
    if (statusRaw !== undefined && statusRaw !== '') {
      if (typeof statusRaw !== 'string' || !STATUSES.includes(statusRaw)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '재직 구분 값이 올바르지 않습니다.');
      }
      employmentStatus = statusRaw;
    }
    const deptRaw = q['departmentId'];
    let departmentId: string | null = null;
    if (deptRaw !== undefined && deptRaw !== '') {
      if (typeof deptRaw !== 'string' || !/^\d+$/.test(deptRaw)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '소속 부서 ID 형식이 올바르지 않습니다.');
      }
      departmentId = deptRaw;
    }
    return transaction(async (db) => {
      const where = `WHERE (CAST(:employmentStatus AS varchar) IS NULL OR employment_status = CAST(:employmentStatus AS varchar))
         AND (CAST(:departmentId AS bigint) IS NULL OR department_id = CAST(:departmentId AS bigint))`;
      const items = await db.query(
        `SELECT hr_record_id AS "hrRecordId", employee_id AS "employeeId", department_id AS "departmentId",
           position_name AS "positionName", employment_status AS "employmentStatus",
           to_char(hire_date, 'YYYY-MM-DD') AS "hireDate",
           to_char(retirement_date, 'YYYY-MM-DD') AS "retirementDate"
         FROM hr_record
         ${where}
         ORDER BY hr_record_id DESC
         LIMIT CAST(:limit AS int) OFFSET CAST(:offset AS int)`,
        { employmentStatus, departmentId, limit: pageSize, offset: page * pageSize },
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" FROM hr_record ${where}`,
        { employmentStatus, departmentId },
      );
      return { items, page, size: pageSize, total: Number(counted[0]['total']) };
    });
  }
}

