import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const STATUSES = ['재직', '휴직', '단축근무', '퇴직'];
const STATUS_OPTIONS: [string, string][] = STATUSES.map((s) => [s, s]);
const SIZE = 20;

const EMPTY: Row = { employmentStatus: '재직' };

function cleanBody(form: Row): Row {
  const body: Row = {};
  Object.keys(form).forEach((k) => {
    const v = form[k];
    if (v !== '' && v !== undefined && v !== null) {
      body[k] = v;
    }
  });
  return body;
}

export default function FnSfr01201Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [mode, setMode] = useState<'' | 'create' | 'edit'>('');
  const [form, setForm] = useState<Row>(EMPTY);

  const list = useData<Page>(
    () => call<Page>('GET', '/hr-records', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const counts = useData<number[]>(
    () =>
      Promise.all(
        STATUSES.map((s) =>
          call<Page>('GET', '/hr-records', role, undefined, { employmentStatus: s, page: 0, size: 1 }).then((r) => r.total),
        ),
      ),
    [role],
  );

  const set = (key: string) => (v: unknown) => setForm({ ...form, [key]: v });

  const search = () => {
    setPage(0);
    setApplied({ employmentStatus: status, departmentId });
  };
  const reset = () => {
    setStatus('');
    setDepartmentId('');
    setPage(0);
    setApplied({});
  };
  const refresh = () => {
    list.reload();
    counts.reload();
  };

  const openCreate = () => {
    setForm(EMPTY);
    setMode('create');
  };
  const openEdit = (row: Row) => {
    setForm({
      departmentId: row['departmentId'] ?? '',
      positionName: row['positionName'] ?? '',
      employmentStatus: row['employmentStatus'] ?? '',
      hireDate: row['hireDate'] ?? '',
      retirementDate: row['retirementDate'] ?? '',
    });
    setDetail(row);
    setMode('edit');
  };

  const submitCreate = async () => {
    if (form['employeeId'] === undefined || form['employeeId'] === '') {
      throw new Error('임직원 ID를 선택해 주세요.');
    }
    if (!form['employmentStatus']) {
      throw new Error('재직 구분을 선택해 주세요.');
    }
    if (form['employmentStatus'] === '퇴직' && !form['retirementDate']) {
      throw new Error('퇴직으로 등록하려면 퇴직일을 입력해 주세요.');
    }
    await call('POST', '/hr-records', role, cleanBody(form));
    notify('인사정보를 등록했습니다.');
    setMode('');
    refresh();
  };

  const submitEdit = async () => {
    if (!detail) {
      return;
    }
    if (form['employmentStatus'] === '퇴직' && !form['retirementDate']) {
      throw new Error('퇴직으로 변경하려면 퇴직일을 입력해 주세요.');
    }
    await call('PATCH', '/hr-records/' + String(detail['hrRecordId']), role, cleanBody(form));
    notify('인사정보를 수정했습니다.');
    setMode('');
    setDetail(null);
    refresh();
  };

  const rows = list.data?.items ?? [];
  const tiles: [string, React.ReactNode][] = STATUSES.map((s, i) => [s, <Num value={counts.data ? counts.data[i] : 0} />]);

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>재직 구분별 인원</h2>
        <Tiles items={tiles} />
      </section>

      <section className='box span-12'>
        <h2>인사정보 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='재직 구분'>
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
          <Field label='소속 부서 ID'>
            <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type='button' onClick={openCreate}>인사정보 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => {
            setDetail(row);
            setMode('');
          }}
          empty='인사정보가 없습니다.'
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table='employee' role={role} value={r['employeeId']} /> },
            { key: 'departmentId', label: '소속 부서 ID', render: (r) => <RefName table='department' role={role} value={r['departmentId']} /> },
            { key: 'positionName', label: '직위' },
            { key: 'employmentStatus', label: '재직 구분', render: (r) => <Badge value={r['employmentStatus']} /> },
            { key: 'hireDate', label: '입사일', render: (r) => <DateText value={r['hireDate']} /> },
            { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r['retirementDate']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      {detail && mode === '' ? (
        <Drawer title='인사정보 상세' onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['인사정보 ID', String(detail['hrRecordId'])],
              ['임직원 ID', <RefName table='employee' role={role} value={detail['employeeId']} />],
              ['소속 부서 ID', <RefName table='department' role={role} value={detail['departmentId']} />],
              ['직위', String(detail['positionName'] ?? '')],
              ['재직 구분', <Badge value={detail['employmentStatus']} />],
              ['입사일', <DateText value={detail['hireDate']} />],
              ['퇴직일', <DateText value={detail['retirementDate']} />],
            ]}
          />
          <button type='button' onClick={() => openEdit(detail)}>수정</button>
        </Drawer>
      ) : null}

      {mode === 'create' ? (
        <Drawer title='인사정보 등록' onClose={() => setMode('')}>
          <Form onSubmit={submitCreate} submit='등록'>
            <Field label='임직원 ID' required>
              <LookupSelect table='employee' role={role} value={form['employeeId']} onChange={set('employeeId')} />
            </Field>
            <Field label='소속 부서 ID'>
              <LookupSelect table='department' role={role} value={form['departmentId']} onChange={set('departmentId')} />
            </Field>
            <Field label='직위'>
              <TextInput value={form['positionName']} onChange={set('positionName')} />
            </Field>
            <Field label='생년월일'>
              <DateInput value={form['birthDate']} onChange={set('birthDate')} />
            </Field>
            <Field label='성별'>
              <Select value={form['gender']} onChange={set('gender')} options={[['M', '남'], ['F', '여']]} />
            </Field>
            <Field label='주소' wide>
              <TextInput value={form['address']} onChange={set('address')} />
            </Field>
            <Field label='연락처'>
              <TextInput value={form['phoneNo']} onChange={set('phoneNo')} />
            </Field>
            <Field label='재직 구분' required>
              <Select value={form['employmentStatus']} onChange={set('employmentStatus')} options={STATUS_OPTIONS} />
            </Field>
            <Field label='입사일'>
              <DateInput value={form['hireDate']} onChange={set('hireDate')} />
            </Field>
            <Field label='퇴직일' hint='재직 구분이 퇴직이면 필수'>
              <DateInput value={form['retirementDate']} onChange={set('retirementDate')} />
            </Field>
            <Field label='기본급'>
              <NumberInput value={form['baseSalary']} onChange={set('baseSalary')} />
            </Field>
            <Field label='급여 은행명'>
              <TextInput value={form['bankName']} onChange={set('bankName')} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'edit' && detail ? (
        <Drawer title='인사정보 수정' onClose={() => setMode('')}>
          <Form onSubmit={submitEdit} submit='저장'>
            <Field label='소속 부서 ID'>
              <LookupSelect table='department' role={role} value={form['departmentId']} onChange={set('departmentId')} />
            </Field>
            <Field label='직위'>
              <TextInput value={form['positionName']} onChange={set('positionName')} />
            </Field>
            <Field label='주소' wide>
              <TextInput value={form['address']} onChange={set('address')} />
            </Field>
            <Field label='연락처'>
              <TextInput value={form['phoneNo']} onChange={set('phoneNo')} />
            </Field>
            <Field label='재직 구분'>
              <Select value={form['employmentStatus']} onChange={set('employmentStatus')} options={STATUS_OPTIONS} />
            </Field>
            <Field label='입사일'>
              <DateInput value={form['hireDate']} onChange={set('hireDate')} />
            </Field>
            <Field label='퇴직일' hint='재직 구분을 퇴직으로 바꾸면 필수'>
              <DateInput value={form['retirementDate']} onChange={set('retirementDate')} />
            </Field>
            <Field label='기본급'>
              <NumberInput value={form['baseSalary']} onChange={set('baseSalary')} />
            </Field>
            <Field label='급여 은행명'>
              <TextInput value={form['bankName']} onChange={set('bankName')} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
